/**
 * Star System Generator (p. 243). Rolls body counts (modified by brightness
 * class), rolls features for gas giants and asteroid belts, builds the body
 * list (gas giants get D6+4 moons) and produces one star-system location plus
 * a stub planet per terrestrial or ice body (`within` the system). Full worlds
 * are generated by chaining into `alien.world.create` per body.
 */
import type { Procedure, ProcedureContext, ProducedEntity } from "@campaign-forge/module-sdk";
import { input, isObj, list, num, obj, str } from "./helpers";

interface Body {
  type: "gas-giant" | "terrestrial" | "ice" | "asteroid-belt";
  name: string;
  features?: string[];
  moons?: number;
  planetType?: "terrestrial" | "ice";
}

const ROMAN = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII"];

function bodies(ctx: ProcedureContext): Body[] {
  const v = ctx.get("bodies");
  return Array.isArray(v) ? (v.filter(isObj) as unknown as Body[]) : [];
}

/** Bodies that can become full worlds, in order. */
export function worldBodies(ctx: ProcedureContext): Body[] {
  return bodies(ctx).filter((b) => b.type === "terrestrial" || b.type === "ice");
}

const MAX_CHAINED_BODIES = 6;

export const systemCreate: Procedure = {
  id: "alien.system.create",
  name: "Star System Generator",
  description: "Roll the system's bodies from the star's brightness class, then generate each terrestrial or ice body as a full world.",
  page: 243,
  inputs: {
    type: "object",
    properties: {
      starClass: { type: "string", enum: ["O", "B", "A", "F", "G", "K", "M"], default: "G" },
      brightness: { type: "string", enum: ["Ia", "Ib", "II", "III", "IV", "V", "D"], default: "V" },
      region: { type: "string", enum: ["core", "outer-veil", "outer-rim", "frontier", "far-reach"], default: "frontier" },
      allegiance: { type: "string", enum: ["uas", "3we", "upp", "icsc", "independent", "unknown"], default: "unknown" },
      name: { type: "string", description: "System designation; generated when absent." },
    },
  },
  steps: [
    {
      id: "designation",
      title: "Designation",
      compute: (ctx, rng) => {
        const given = input<string>(ctx, "name");
        if (typeof given === "string" && given.trim() !== "") return given.trim();
        const letters = "ABCDEFGHJKLMNPRSTUVWXYZ";
        const a = letters[rng.int(0, letters.length - 1)] ?? "A";
        return `${a}${rng.int(10, 99)}-${rng.int(100, 999)}`;
      },
    },
    { id: "objects", title: "System objects", table: "alien.system.objects", page: 243 },
    {
      id: "gasGiantFeatures",
      title: "Gas giant features",
      table: "alien.system.gas-giant-features",
      reads: ["objects"],
      repeat: (ctx) => num(obj(ctx, "objects").gasGiants),
      skipIf: (ctx) => num(obj(ctx, "objects").gasGiants) === 0,
      page: 243,
    },
    {
      id: "asteroidBeltFeatures",
      title: "Asteroid belt features",
      table: "alien.system.asteroid-belt-features",
      reads: ["objects"],
      repeat: (ctx) => num(obj(ctx, "objects").asteroidBelts),
      skipIf: (ctx) => num(obj(ctx, "objects").asteroidBelts) === 0,
      page: 243,
    },
    {
      id: "bodies",
      title: "Body list",
      reads: ["objects", "gasGiantFeatures", "asteroidBeltFeatures"],
      compute: (ctx, rng): Body[] => {
        const o = obj(ctx, "objects");
        const system = str(ctx.get("designation"), "System");
        const out: Body[] = [];
        const gg = list(ctx, "gasGiantFeatures");
        const ab = list(ctx, "asteroidBeltFeatures");
        // Inner to outer: terrestrials, asteroid belts, gas giants, ice worlds.
        for (let i = 0; i < num(o.terrestrials); i++) out.push({ type: "terrestrial", name: "", planetType: "terrestrial" });
        for (let i = 0; i < num(o.asteroidBelts); i++) out.push({ type: "asteroid-belt", name: "", features: [str(ab[i]?.label)].filter(Boolean) });
        for (let i = 0; i < num(o.gasGiants); i++) {
          out.push({ type: "gas-giant", name: "", features: [str(gg[i]?.label)].filter(Boolean), moons: rng.int(1, 6) + 4 });
        }
        for (let i = 0; i < num(o.icePlanets); i++) out.push({ type: "ice", name: "", planetType: "ice" });
        return out.map((b, i) => ({ ...b, name: `${system} ${ROMAN[i] ?? String(i + 1)}` }));
      },
    },
  ],
  produce: (ctx) => {
    const name = str(ctx.get("designation"), "Unnamed system");
    const all = bodies(ctx);
    const region = str(input(ctx, "region"), "frontier");
    const system: ProducedEntity = {
      tempId: "system",
      type: "alien.location",
      name,
      summary: `${str(input(ctx, "starClass"), "G")}${str(input(ctx, "brightness"), "V")} star with ${all.length} bodies`,
      tags: ["star-system"],
      fields: {
        subtype: "star-system",
        starClass: str(input(ctx, "starClass"), "G"),
        brightness: str(input(ctx, "brightness"), "V"),
        region,
        allegiance: str(input(ctx, "allegiance"), "unknown"),
        bodies: all.map((b) => ({ type: b.type, name: b.name, features: b.features ?? [], ...(b.moons !== undefined ? { moons: b.moons } : {}) })),
      },
    };
    const planets: ProducedEntity[] = worldBodies(ctx).map((b, i) => ({
      tempId: `body-${i + 1}`,
      type: "alien.location",
      name: b.name,
      within: "system",
      summary: `${b.type} body; generate as a full world with Main World Creation`,
      tags: ["planet", b.type, "stub"],
      fields: { subtype: "planet", planetType: b.planetType ?? b.type, inhabited: false, region, orbitalComponents: [] },
    }));
    return { entities: [system, ...planets], relationships: [] };
  },
  chains: Array.from({ length: MAX_CHAINED_BODIES }, (_, i) => ({
    procedure: "alien.world.create",
    label: `Generate body ${i + 1} as a full world`,
    inputs: (ctx: ProcedureContext) => {
      const b = worldBodies(ctx)[i];
      return {
        bodyIndex: i,
        name: b?.name,
        planetType: b?.planetType ?? "terrestrial",
        region: str(input(ctx, "region"), "frontier"),
        allegianceBloc: str(input(ctx, "allegiance")) === "icsc" ? "icsc" : str(input(ctx, "allegiance")) === "upp" ? "upp" : "arms",
      };
    },
  })),
};
